// Mantém só mensagens de clientes (ignora avisos de entregue/lido)
const saida = [];
for (const item of $input.all()) {
  const v = item.json;
  const msg = v.messages && v.messages[0];
  if (!msg) continue;
  saida.push({
    json: {
      telefone: msg.from,
      nome: (v.contacts && v.contacts[0] && v.contacts[0].profile && v.contacts[0].profile.name) || '',
      tipo: msg.type,
      texto: msg.type === 'text' ? msg.text.body : '',
      recebida_em: new Date(Number(msg.timestamp) * 1000).toISOString(),
    },
  });
}
return saida;
